use super::*;

/// Every record `lane` has touched, with the state that decides whether it can land.
pub fn lane_changes(conn: &Connection, lane: &str) -> Result<Vec<LaneChange>, String> {
    if lane == MAIN {
        return Err("`main` is the landed graph, not a lane — nothing to compare it against".into());
    }
    let mut st = conn
        .prepare(
            "SELECT r.id, r.rev, COALESCE(r.base_rev, 0)
               FROM record_revs r
              WHERE r.lane = ?1
                AND r.rev = (SELECT MAX(rev) FROM record_revs WHERE id = r.id AND lane = ?1)
              ORDER BY r.id",
        )
        .map_err(|e| e.to_string())?;
    let rows: Vec<(String, i64, i64)> = st
        .query_map([lane], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))
        .map_err(|e| e.to_string())?
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for (id, lane_rev, base_rev) in rows {
        let main_rev = head_rev(conn, &id)?;
        out.push(LaneChange {
            removed: get_in(conn, lane, &id)?.is_none(),
            conflicted: main_rev != base_rev,
            id,
            base_rev,
            main_rev,
            lane_rev,
        });
    }
    Ok(out)
}
